61	/// Whether an attribute list has a specified attribute.
62	pub fn has_attr(attrs: &mut Vec<syn::Attribute>, target: &str) -> bool {
63	    take_attr(attrs, target).is_some()
64	}
65	
66	/// Whether an attribute list has a specified attribute.
67	pub fn parse_attr<T: Parse>(
68	    attrs: &mut Vec<syn::Attribute>,
69	    target: &str,
70	) -> Result<Option<Option<T>>> {
71	    take_attr(attrs, target)
72	        .map(|attr| {
73	            Ok(match attr.meta {
74	                syn::Meta::Path(_) => None,
75	                syn::Meta::List(list) => Some(list.parse_args()?),
76	                syn::Meta::NameValue(meta) => bail!(meta, "not valid here"),
77	            })
78	        })
79	        .transpose()
80	}
81	
82	/// Whether an attribute list has a specified attribute.
83	pub fn take_attr(
84	    attrs: &mut Vec<syn::Attribute>,
85	    target: &str,
86	) -> Option<syn::Attribute> {
87	    attrs
88	        .iter()
89	        .position(|attr| attr.path().is_ident(target))
90	        .map(|i| attrs.remove(i))
91	}
92	
93	/// Ensure that no unrecognized attributes remain.
94	pub fn validate_attrs(attrs: &[syn::Attribute]) -> Result<()> {
95	    for attr in attrs {
96	        if !attr.path().is_ident("doc") && !attr.path().is_ident("derive") {
97	            let ident = attr.path().get_ident().unwrap();
98	            bail!(ident, "unrecognized attribute: {ident}");
99	        }
100	    }
101	    Ok(())
102	}
103	
104	/// Quotes an option literally.
105	pub fn quote_option<T: ToTokens>(option: &Option<T>) -> TokenStream {
106	    if let Some(value) = option {
107	        quote! { Some(#value) }
108	    } else {
109	        quote! { None }
110	    }
111	}
112	
113	/// Parse a metadata key-value pair, separated by `=`.
114	pub fn parse_key_value<K: Token + Default + Parse, V: Parse>(
115	    input: ParseStream,
116	) -> Result<Option<V>> {
117	    if !input.peek(|_| K::default()) {
118	        return Ok(None);
119	    }
120	
121	    let _: K = input.parse()?;
122	    let _: Token![=] = input.parse()?;
123	    let value: V = input.parse::<V>()?;
124	    eat_comma(input);
125	    Ok(Some(value))
126	}
127	
128	/// Parse a metadata key-array pair, separated by `=`.
129	pub fn parse_key_value_array<K: Token + Default + Parse, V: Parse>(
130	    input: ParseStream,
131	) -> Result<Vec<V>> {
132	    Ok(parse_key_value::<K, Array<V>>(input)?.map_or(vec![], |array| array.0))
133	}
134	
135	/// Parse a metadata key-string pair, separated by `=`.
136	pub fn parse_string<K: Token + Default + Parse>(
137	    input: ParseStream,
138	) -> Result<Option<String>> {
139	    Ok(parse_key_value::<K, syn::LitStr>(input)?.map(|s| s.value()))
140	}
141	
142	/// Parse a metadata key-string pair, separated by `=`.
143	pub fn parse_string_array<K: Token + Default + Parse>(
144	    input: ParseStream,
145	) -> Result<Vec<String>> {
146	    Ok(parse_key_value_array::<K, syn::LitStr>(input)?
147	        .into_iter()
148	        .map(|lit| lit.value())
149	        .collect())
150	}
151	
152	/// Parse a metadata flag that can be present or not.
153	pub fn parse_flag<K: Token + Default + Parse>(input: ParseStream) -> Result<bool> {
154	    if input.peek(|_| K::default()) {
155	        let _: K = input.parse()?;
156	        eat_comma(input);
157	        return Ok(true);
158	    }
159	    Ok(false)
160	}
161	
162	/// Parse a comma if there is one.
163	pub fn eat_comma(input: ParseStream) {
164	    if input.peek(Token![,]) {
165	        let _: Token![,] = input.parse().unwrap();
166	    }
167	}
168	
169	/// Determine the normal and title case name of a function, type, or element.
170	pub fn determine_name_and_title(
171	    specified_name: Option<String>,
172	    specified_title: Option<String>,
173	    ident: &syn::Ident,
174	    trim: Option<fn(&str) -> &str>,
175	) -> Result<(String, String)> {
176	    let name = {
177	        let trim = trim.unwrap_or(|s| s);
178	        let default = trim(&ident.to_string()).to_kebab_case();
179	        if specified_name.as_ref() == Some(&default) {
180	            bail!(ident, "name was specified unnecessarily");
181	        }
182	        specified_name.unwrap_or(default)
183	    };
184	
185	    let title = {
186	        let default = name.to_title_case();
187	        if specified_title.as_ref() == Some(&default) {
188	            bail!(ident, "title was specified unnecessarily");
189	        }
190	        specified_title.unwrap_or(default)
191	    };
192	
193	    Ok((name, title))
194	}
