11	/// Expand the `#[ty]` macro.
12	pub fn ty(stream: TokenStream, mut item: syn::Item) -> Result<TokenStream> {
13	    let meta: Meta = syn::parse2(stream)?;
14	    let mut bare: BareType;
15	    let (ident, attrs, keep) = match &mut item {
16	        syn::Item::Struct(item) => (&item.ident, &mut item.attrs, true),
17	        syn::Item::Type(item) => (&item.ident, &mut item.attrs, true),
18	        syn::Item::Enum(item) => (&item.ident, &mut item.attrs, true),
19	        syn::Item::Verbatim(item) => {
20	            bare = syn::parse2(item.clone())?;
21	            (&bare.ident, &mut bare.attrs, false)
22	        }
23	        _ => bail!(item, "invalid type item"),
24	    };
25	    let ty = parse(meta, ident.clone(), attrs)?;
26	    attrs.retain(|attr| !attr.path().is_ident("doc"));
27	    Ok(create(&ty, keep.then_some(&item)))
28	}
29	
30	/// Holds all relevant parsed data about a type.
