90	/// A field of an [element definition][`Elem`].
91	struct Field {
92	    /// The index of the field among all.
93	    i: u8,
94	    /// The name of this field.
95	    ident: Ident,
96	    /// The identifier `with_{ident}`.
97	    with_ident: Ident,
98	    /// The visibility of this field.
99	    vis: syn::Visibility,
100	    /// The type of this field.
101	    ty: syn::Type,
102	    /// The field's identifier as exposed to Typst.
103	    name: String,
104	    /// The documentation for this field as a string.
105	    docs: String,
106	    /// Whether this field is positional (as opposed to named).
107	    positional: bool,
108	    /// Whether this field is required.
109	    required: bool,
110	    /// Whether this field is variadic; that is, has its values
111	    /// taken from a variable number of arguments.
112	    variadic: bool,
113	    /// Whether this field has a `#[fold]` attribute.
114	    fold: bool,
115	    /// Whether this field is excluded from documentation.
116	    internal: bool,
117	    /// Whether this field exists only in documentation.
118	    external: bool,
119	    /// Whether this field has a `#[ghost]` attribute.
120	    ghost: bool,
121	    /// Whether this field has a `#[synthesized]` attribute.
122	    synthesized: bool,
123	    /// The contents of the `#[parse({..})]` attribute, if any.
124	    parse: Option<BlockWithReturn>,
125	    /// The contents of the `#[default(..)]` attribute, if any.
126	    default: Option<syn::Expr>,
127	}
128	
129	/// The `..` in `#[elem(..)]`.
130	struct Meta {
131	    scope: bool,
132	    name: Option<String>,
133	    title: Option<String>,
134	    since: Option<Since>,
135	    keywords: Vec<String>,
136	    capabilities: Vec<Ident>,
137	}
138	
139	impl Parse for Meta {
140	    fn parse(input: ParseStream) -> Result<Self> {
141	        Ok(Self {
142	            scope: parse_flag::<kw::scope>(input)?,
143	            name: parse_string::<kw::name>(input)?,
144	            title: parse_string::<kw::title>(input)?,
145	            since: parse_key_value::<kw::since, Since>(input)?,
146	            keywords: parse_string_array::<kw::keywords>(input)?,
147	            capabilities: Punctuated::<Ident, Token![,]>::parse_terminated(input)?
148	                .into_iter()
149	                .collect(),
150	        })
151	    }
152	}
153	
154	/// Parse details about the element from its struct definition.
155	fn parse(stream: TokenStream, body: &syn::ItemStruct) -> Result<Elem> {
156	    let meta: Meta = syn::parse2(stream)?;
157	    let (name, title) = determine_name_and_title(
158	        meta.name,
159	        meta.title,
160	        &body.ident,
161	        Some(|base| base.trim_end_matches("Elem")),
162	    )?;
163	
164	    let docs = documentation(&body.attrs);
165	
166	    let syn::Fields::Named(named) = &body.fields else {
167	        bail!(body, "expected named fields");
168	    };
169	
170	    let mut fields = named.named.iter().map(parse_field).collect::<Result<Vec<_>>>()?;
171	    fields.sort_by_key(|field| field.internal);
172	    for (i, field) in fields.iter_mut().enumerate() {
173	        field.i = i as u8;
174	    }
175	
176	    if fields.iter().any(|field| field.ghost && !field.internal)
177	        && meta.capabilities.iter().all(|capability| capability != "Construct")
178	    {
179	        bail!(
180	            body.ident,
181	            "cannot have public ghost fields and an auto-generated constructor",
182	        );
183	    }
184	
185	    Ok(Elem {
186	        name,
187	        title,
188	        since: meta.since,
189	        scope: meta.scope,
190	        keywords: meta.keywords,
191	        docs,
192	        vis: body.vis.clone(),
193	        ident: body.ident.clone(),
194	        capabilities: meta.capabilities,
195	        fields,
196	    })
197	}
198	
199	fn parse_field(field: &syn::Field) -> Result<Field> {
200	    let Some(ident) = field.ident.clone() else {
201	        bail!(field, "expected named field");
202	    };
203	
204	    if ident == "label" {
205	        bail!(ident, "invalid field name `label`");
206	    }
207	
208	    let mut attrs = field.attrs.clone();
209	    let variadic = has_attr(&mut attrs, "variadic");
210	    let required = has_attr(&mut attrs, "required") || variadic;
211	    let positional = has_attr(&mut attrs, "positional") || required;
212	
213	    let field = Field {
214	        i: 0,
215	        ident: ident.clone(),
216	        with_ident: format_ident!("with_{ident}"),
217	        vis: field.vis.clone(),
218	        ty: field.ty.clone(),
219	        name: ident.to_string().to_kebab_case(),
220	        docs: documentation(&attrs),
221	        positional,
222	        required,
223	        variadic,
224	        fold: has_attr(&mut attrs, "fold"),
225	        internal: has_attr(&mut attrs, "internal"),
226	        external: has_attr(&mut attrs, "external"),
227	        ghost: has_attr(&mut attrs, "ghost"),
228	        synthesized: has_attr(&mut attrs, "synthesized"),
229	        parse: parse_attr(&mut attrs, "parse")?.flatten(),
230	        default: parse_attr::<syn::Expr>(&mut attrs, "default")?.flatten(),
231	    };
232	
233	    if field.required && field.synthesized {
234	        bail!(ident, "required fields cannot be synthesized");
235	    }
236	
237	    if (field.required || field.synthesized)
238	        && (field.default.is_some() || field.fold || field.ghost)
239	    {
240	        bail!(ident, "required and synthesized fields cannot be default, fold, or ghost");
241	    }
242	
243	    validate_attrs(&attrs)?;
244	
245	    Ok(field)
246	}
247	
248	/// Produce the element's definition.
249	fn create(element: &Elem) -> Result<TokenStream> {
250	    // The struct itself.
251	    let struct_ = create_struct(element);
252	
253	    // Implementations.
254	    let inherent_impl = create_inherent_impl(element);
255	    let native_element_impl = create_native_elem_impl(element)?;
256	    let field_impls =
257	        element.fields.iter().map(|field| create_field_impl(element, field));
258	    let construct_impl =
259	        element.cannot("Construct").then(|| create_construct_impl(element));
260	    let set_impl = element.cannot("Set").then(|| create_set_impl(element));
261	    let mathy_impl = element.can("Mathy").then(|| create_mathy_impl(element));
262	
263	    // We use a const block to create an anonymous scope, as to not leak any
264	    // local definitions.
265	    Ok(quote! {
266	        #struct_
267	
268	        const _: () = {
269	            #inherent_impl
270	            #native_element_impl
271	            #(#field_impls)*
272	            #construct_impl
273	            #set_impl
274	            #mathy_impl
275	        };
276	    })
277	}
278	
279	/// Create the struct definition itself.
280	fn create_struct(element: &Elem) -> TokenStream {
281	    let Elem { vis, ident, docs, .. } = element;
282	
283	    let debug = element.cannot("Debug").then(|| quote! { Debug, });
284	    let fields = element.struct_fields().map(create_field);
285	    let oneliner = oneliner(docs);
286	
287	    quote! {
288	        #[doc = #oneliner]
289	        #[derive(Hash, #debug Clone)]
290	        #[expect(rustdoc::broken_intra_doc_links)]
291	        #vis struct #ident {
292	            #(#fields,)*
293	        }
294	    }
295	}
296	
297	/// Create a field declaration for the struct.
298	fn create_field(field: &Field) -> TokenStream {
299	    let Field { i, vis, ident, ty, .. } = field;
300	    if field.required {
301	        quote! { #vis #ident: #ty }
302	    } else if field.synthesized {
303	        quote! { #vis #ident: ::std::option::Option<#ty> }
304	    } else {
305	        quote! { #vis #ident: #foundations::Settable<Self, #i> }
306	    }
307	}
308	
309	/// Create the inherent implementation of the struct.
310	fn create_inherent_impl(element: &Elem) -> TokenStream {
311	    let Elem { ident, .. } = element;
312	
313	    let new_func = create_new_func(element);
314	    let with_field_methods = element.accessor_fields().map(create_with_field_method);
315	
316	    let style_consts = element.real_fields().map(|field| {
317	        let Field { i, vis, ident, .. } = field;
318	        quote! {
319	            #vis const #ident: #foundations::Field<Self, #i>
320	                = #foundations::Field::new();
321	        }
322	    });
323	
324	    quote! {
325	        impl #ident {
326	            #new_func
327	            #(#with_field_methods)*
328	        }
329	        #[expect(non_upper_case_globals)]
330	        impl #ident {
331	            #(#style_consts)*
332	        }
333	    }
334	}
335	
336	/// Create the `new` function for the element.
337	fn create_new_func(element: &Elem) -> TokenStream {
338	    let params = element
339	        .struct_fields()
340	        .filter(|field| field.required)
341	        .map(|Field { ident, ty, .. }| quote! { #ident: #ty });
342	
343	    let fields = element.struct_fields().map(|field| {
344	        let ident = &field.ident;
345	        if field.required {
346	            quote! { #ident }
347	        } else if field.synthesized {
348	            quote! { #ident: None }
349	        } else {
350	            quote! { #ident: #foundations::Settable::new() }
351	        }
352	    });
353	
354	    quote! {
355	        /// Create a new instance of the element.
356	        pub fn new(#(#params),*) -> Self {
357	            Self { #(#fields,)* }
358	        }
359	    }
360	}
361	
362	/// Create a builder-style setter method for a field.
363	fn create_with_field_method(field: &Field) -> TokenStream {
364	    let Field { vis, ident, with_ident, name, ty, .. } = field;
365	    let doc = format!("Builder-style setter for the [`{name}`](Self::{ident}) field.");
366	
367	    let expr = if field.required {
368	        quote! { self.#ident = #ident }
369	    } else if field.synthesized {
370	        quote! { self.#ident = Some(#ident) }
371	    } else {
372	        quote! { self.#ident.set(#ident) }
373	    };
374	
375	    quote! {
376	        #[doc = #doc]
377	        #vis fn #with_ident(mut self, #ident: #ty) -> Self {
378	            #expr;
379	            self
380	        }
381	    }
382	}
383	
384	/// Creates the element's `NativeElement` implementation.
385	fn create_native_elem_impl(element: &Elem) -> Result<TokenStream> {
386	    let Elem {
387	        name, ident, title, since, scope, keywords, docs, ..
388	    } = element;
389	    let def_site_key = ident.to_string();
390	
391	    let since = if let Some(since) = since {
392	        quote! { Some(#since) }
393	    } else {
394	        quote! { None }
395	    };
396	
397	    let fields = element.fields.iter().filter(|field| !field.internal).map(|field| {
398	        let i = field.i;
399	        if field.external {
400	            quote! { #foundations::ExternalFieldData::<#ident, #i>::vtable() }
401	        } else if field.variadic {
402	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable_variadic() }
403	        } else if field.required {
404	            quote! { #foundations::RequiredFieldData::<#ident, #i>::vtable() }
405	        } else if field.synthesized {
406	            quote! { #foundations::SynthesizedFieldData::<#ident, #i>::vtable() }
407	        } else if field.ghost {
408	            quote! { #foundations::SettablePropertyData::<#ident, #i>::vtable() }
409	        } else {
410	            quote! { #foundations::SettableFieldData::<#ident, #i>::vtable() }
411	        }
412	    });
413	
414	    let field_arms = element
415	        .fields
416	        .iter()
417	        .filter(|field| !field.internal && !field.external)
418	        .map(|field| {
419	            let Field { name, i, .. } = field;
420	            quote! { #name => Some(#i) }
421	        });
422	    let field_id = quote! {
423	        |name| match name {
424	            #(#field_arms,)*
425	            _ => None,
426	        }
427	    };
428	
429	    let capable_func = create_capable_func(element);
430	    let introspection = create_introspection_capabilities(element)?;
431	
432	    let with_keywords =
433	        (!keywords.is_empty()).then(|| quote! { .with_keywords(&[#(#keywords),*]) });
434	    let with_repr = element.can("Repr").then(|| quote! { .with_repr() });
435	    let with_partial_eq = element.can("PartialEq").then(|| quote! { .with_partial_eq() });
436	    let with_local_name = element.can("LocalName").then(|| quote! { .with_local_name() });
437	    let with_scope = scope.then(|| quote! { .with_scope() });
438	
439	    Ok(quote! {
440	        unsafe impl #foundations::NativeElement for #ident {
441	            const ELEM: #foundations::Element = #foundations::Element::from_vtable({
442	                static STORE: #foundations::LazyElementStore
443	                    = #foundations::LazyElementStore::new();
444	                static VTABLE: #foundations::ContentVtable =
445	                    #foundations::ContentVtable::new::<#ident>(
446	                        #name,
447	                        #title,
448	                        #since,
449	                        #docs,
450	                        ::typst_utils::DefSite { path: file!(), key: #def_site_key },
451	                        &[#(#fields),*],
452	                        #field_id,
453	                        #capable_func,
454	                        #introspection,
455	                        || &STORE,
456	                    ) #with_keywords
457	                    #with_repr
458	                    #with_partial_eq
459	                    #with_local_name
460	                    #with_scope
461	                    .erase();
462	                &VTABLE
463	            });
464	        }
465	    })
466	}
467	
468	/// Creates the appropriate trait implementation for a field.
469	fn create_field_impl(element: &Elem, field: &Field) -> TokenStream {
470	    let elem_ident = &element.ident;
471	    let Field { i, ty, ident, default, positional, name, docs, .. } = field;
472	    let def_site_key = format!("{elem_ident}::{ident}");
473	    let def_site = quote! {
474	        ::typst_utils::DefSite { path: file!(), key: #def_site_key }
475	    };
476	
477	    let default = match default {
478	        Some(default) => quote! { || #default },
479	        None => quote! { std::default::Default::default },
480	    };
481	
482	    if field.external {
483	        quote! {
484	            impl #foundations::ExternalField<#i> for #elem_ident {
485	                type Type = #ty;
486	                const FIELD: #foundations::ExternalFieldData<Self, #i> =
487	                    #foundations::ExternalFieldData::<Self, #i>::new(
488	                        #name,
489	                        #docs,
490	                        #def_site,
491	                        #default,
492	                    );
493	            }
494	        }
495	    } else if field.required {
496	        quote! {
497	            impl #foundations::RequiredField<#i> for #elem_ident {
498	                type Type = #ty;
499	                const FIELD: #foundations::RequiredFieldData<Self, #i> =
500	                    #foundations::RequiredFieldData::<Self, #i>::new(
501	                        #name,
502	                        #docs,
503	                        #def_site,
504	                        |elem| &elem.#ident,
505	                    );
506	            }
507	        }
508	    } else if field.synthesized {
509	        quote! {
510	            impl #foundations::SynthesizedField<#i> for #elem_ident {
511	                type Type = #ty;
512	                const FIELD: #foundations::SynthesizedFieldData<Self, #i> =
513	                    #foundations::SynthesizedFieldData::<Self, #i>::new(
514	                        #name,
515	                        #docs,
516	                        #def_site,
517	                        |elem| &elem.#ident,
518	                    );
519	            }
520	        }
521	    } else {
522	        let slot = quote! {
523	            || {
524	                static LOCK: ::std::sync::OnceLock<#ty> = ::std::sync::OnceLock::new();
525	                &LOCK
526	            }
527	        };
528	
529	        let with_fold = field.fold.then(|| quote! { .with_fold() });
530	        let refable = (!field.fold).then(|| {
531	            quote! {
532	                impl #foundations::RefableProperty<#i> for #elem_ident {}
533	            }
534	        });
535	
536	        if field.ghost {
537	            quote! {
538	                impl #foundations::SettableProperty<#i> for #elem_ident {
539	                    type Type = #ty;
540	                    const FIELD: #foundations::SettablePropertyData<Self, #i> =
541	                        #foundations::SettablePropertyData::<Self, #i>::new(
542	                            #name,
543	                            #docs,
544	                            #def_site,
545	                            #positional,
546	                            #default,
547	                            #slot,
548	                        ) #with_fold;
549	                }
550	                #refable
551	            }
552	        } else {
553	            quote! {
554	                impl #foundations::SettableField<#i> for #elem_ident {
555	                    type Type = #ty;
556	                    const FIELD: #foundations::SettableFieldData<Self, #i> =
557	                        #foundations::SettableFieldData::<Self, #i>::new(
558	                            #name,
559	                            #docs,
560	                            #def_site,
561	                            #positional,
562	                            |elem| &elem.#ident,
563	                            |elem| &mut elem.#ident,
564	                            #default,
565	                            #slot,
566	                        ) #with_fold;
567	                }
568	                #refable
569	            }
570	        }
571	    }
572	}
573	
574	/// Creates the element's `Construct` implementation.
575	fn create_construct_impl(element: &Elem) -> TokenStream {
576	    let ident = &element.ident;
577	    let setup = element.construct_fields().map(|field| {
578	        let (prefix, value) = create_field_parser(field);
579	        let ident = &field.ident;
580	        quote! {
581	            #prefix
582	            let #ident = #value;
583	        }
584	    });
585	
586	    let fields = element.struct_fields().map(|field| {
587	        let ident = &field.ident;
588	        if field.required {
589	            quote! { #ident }
590	        } else if field.synthesized {
591	            quote! { #ident: None }
592	        } else {
593	            quote! { #ident: #foundations::Settable::from(#ident) }
594	        }
595	    });
596	
597	    quote! {
598	        impl #foundations::Construct for #ident {
599	            fn construct(
600	                engine: &mut ::typst_library::engine::Engine,
601	                args: &mut #foundations::Args,
602	            ) -> ::typst_library::diag::SourceResult<#foundations::Content> {
603	                #(#setup)*
604	                Ok(#foundations::Content::new(Self { #(#fields),* }))
605	            }
606	        }
607	    }
608	}
609	
610	/// Creates the element's `Set` implementation.
611	fn create_set_impl(element: &Elem) -> TokenStream {
612	    let ident = &element.ident;
613	    let handlers = element.set_fields().map(|field| {
614	        let field_ident = &field.ident;
615	        let (prefix, value) = create_field_parser(field);
616	        quote! {
617	            #prefix
618	            if let Some(value) = #value {
619	                styles.set(Self::#field_ident, value);
620	            }
621	        }
622	    });
623	
624	    quote! {
625	        impl #foundations::Set for #ident {
626	            fn set(
627	                engine: &mut ::typst_library::engine::Engine,
628	                args: &mut #foundations::Args,
629	            ) -> ::typst_library::diag::SourceResult<#foundations::Styles> {
630	                let mut styles = #foundations::Styles::new();
631	                #(#handlers)*
632	                Ok(styles)
633	            }
634	        }
635	    }
636	}
637	
638	/// Create argument parsing code for a field.
639	fn create_field_parser(field: &Field) -> (TokenStream, TokenStream) {
640	    if let Some(BlockWithReturn { prefix, expr }) = &field.parse {
641	        return (quote! { #(#prefix);* }, quote! { #expr });
642	    }
643	
644	    let name = &field.name;
645	    let value = if field.variadic {
646	        quote! { args.all()? }
647	    } else if field.required {
648	        quote! { args.expect(#name)? }
649	    } else if field.positional {
650	        quote! { args.find()? }
651	    } else {
652	        quote! { args.named(#name)? }
653	    };
654	
655	    (quote! {}, value)
656	}
657	
658	/// Creates the element's casting vtable.
659	fn create_capable_func(element: &Elem) -> TokenStream {
660	    // Forbidden capabilities, i.e capabilities that are not object safe or
661	    // introspection capabilities that are handled otherwise.
662	    const FORBIDDEN: &[&str] = &[
663	        // Not object safe.
664	        "Debug",
665	        "PartialEq",
666	        "Hash",
667	        "Construct",
668	        "Set",
669	        "Repr",
670	        "LocalName",
671	        // Introspection capabilities.
672	        "Locatable",
673	        "Unqueriable",
674	        "Tagged",
675	    ];
676	
677	    let ident = &element.ident;
678	    let relevant = element
679	        .capabilities
680	        .iter()
681	        .filter(|&ident| !FORBIDDEN.contains(&(&ident.to_string() as &str)));
682	
683	    let checks = relevant.map(|capability| {
684	        quote! {
685	            if capability == ::std::any::TypeId::of::<dyn #capability>() {
686	                // Safety: The vtable function doesn't require initialized
687	                // data, so it's fine to use a dangling pointer.
688	                return Some(unsafe {
689	                    ::typst_utils::fat::vtable(dangling as *const dyn #capability)
690	                });
691	            }
692	        }
693	    });
694	
695	    quote! {
